recio_unitario", "align": "right", "w": 32, "visible": true, "format": "currency"}, {"label": "Importe", "field": "importe", "align": "right", "w": 32, "visible": true, "format": "currency"}], "rowsBinding": "items", "groupBy": "categoria", "bordered": true, "lightHead": false, "zebra": false, "headerColorToken": "ink"}, {"id": "totals-banner", "x": 11.5, "y": 200, "w": 187, "zIndex": 203, "required": true, "flowAfter": "items-table", "flowGap": 5.5, "type": "totals-banner", "rows": [{"label": "Subtotal", "valueVariable": "subtotal", "labelColorToken": "ink-faint", "valueColorToken": "surface", "bold": false, "fontSize": 9.5}, {"label": "Fee de agencia", "valueVariable": "fee_agencia", "labelColorToken": "ink-faint", "valueColorToken": "surface", "bold": false, "fontSize": 9.5}, {"label": "General", "valueVariable": "general", "labelColorToken": "orange", "valueColorToken": "orange", "bold": true, "fontSize": 10.5}, {"label": "Descuento", "valueVariable": "descuento_monto", "labelColorToken": "orange-soft", "valueColorToken": "orange-soft", "bold": false, "fontSize": 9.5, "negate": true, "visibleIf": "descuento_monto"}, {"label": "IVA (16%)", "valueVariable": "iva", "labelColorToken": "ink-faint", "valueColorToken": "surface", "bold": false, "fontSize": 9.5, "visibleIf": "iva_activo"}, {"label": "TOTAL", "valueVariable": "total", "labelColorToken": "surface", "valueColorToken": "surface", "bold": true, "fontSize": 10.5}], "bgColorToken": "ink"}, {"id": "logo-serenata", "x": 16.4, "y": 200, "w": 105.2, "h": 14.79, "zIndex": 204, "flowAfter": "items-table", "flowGap": 5.5, "type": "image", "src": "logo-serenata"}, {"id": "notas-label", "x": 11.5, "y": 200, "w": 187, "h": 8, "zIndex": 205, "flowAfter": "totals-banner", "flowGap": 8.8, "visibleIf": "notas", "type": "text", "text": "NOTAS", "size": 10, "bold": true, "align": "left", "colorToken": "surface", "bgToken": "ink"}, {"id": "notas-text", "x": 11.5, "y": 200, "w": 187, "zIndex": 206, "flowAfter": "notas-label", "flowGap": 2, "visibleIf": "notas", "type": "text", "text": "{{notas}}", "size": 8.5, "bold": false, "align": "left", "colorToken": "ink", "wrap": true}, {"id": "generales-label", "x": 11.5, "y": 200, "w": 60, "zIndex": 207, "flowAfter": "notas-text", "flowGap": 7, "type": "text", "text": "GENERALES:", "size": 9.6, "bold": true, "align": "left", "colorToken": "ink"}, {"id": "generales-underline", "x": 11.5, "y": 200, "w": 22.1, "zIndex": 208, "flowAfter": "generales-label", "flowGap": 0.8, "type": "line", "colorToken": "ink", "weight": 0.2}, {"id": "generales-line1", "x": 11.5, "y": 200, "w": 187, "zIndex": 209, "legal": true, "flowAfter": "generales-label", "flowGap": 4.8, "type": "text", "text": "Serenata House se deslinda de cualquier daño o pérdida durante la actividad contratada, salvo de los materiales de producción y el inmueble (en caso de que haya uno contratado).", "size": 8.5, "bold": true, "align": "justify", "colorToken": "ink", "wrap": true}, {"id": "generales-line2", "x": 11.5, "y": 200, "w": 187, "zIndex": 210, "legal": true, "flowAfter": "generales-line1", "flowGap": 1, "type": "text", "text": "Cualquier trabajo o elemento adicional será autorizado por el cliente", "size": 8.5, "bold": false, "align": "justify", "colorToken": "ink", "wrap": true}, {"id": "costos-label", "x": 11.5, "y": 200, "w": 22, "h": 6, "zIndex": 211, "flowAfter": "generales-line2", "flowGap": 7, "type": "text", "text": "COSTOS", "size": 8.8, "bold": true, "align": "left", "colorToken": "surface", "bgToken": "ink"}, {"id": "costos-text", "x": 11.5, "y": 200, "w": 187, "zIndex": 212, "legal": true, "flowAfter": "costos-label", "flowGap": 6.2, "type": "text", "text": "Este presupuesto es 100 % modular y se adaptará a las necesidades del cliente.\nUna vez aterrizada la propuesta al 100 % se ajustarán los costos.\nEste presupuesto es estimativo para desarrollar las actividades mencionadas.\nSe requiere el 50% al contratar el servicio / 50% al finalizar", "size": 8.5, "bold": false, "align": "left", "colorToken": "ink", "wrap": true}, {"id": "cancelacion-label", "x": 11.5, "y": 200, "w": 32, "h": 6, "zIndex": 213, "flowAfter": "costos-text", "flowGap": 6, "type": "text", "text": "CANCELACIÓN", "size": 8.8, "bold": true, "align": "left", "colorToken": "surface", "bgToken": "ink"}, {"id": "cancelacion-text", "x": 11.5, "y": 200, "w": 187, "zIndex": 214, "legal": true, "flowAfter": "cancelacion-label", "flowGap": 6.2, "type": "text", "text": "En caso de cancelación deberá hacerse por escrito con acuse de recibo con 192 horas habiles de anticipacion, toda cancelación realizada por este término genera un cargo del 60% del total generado en la cotización independientemente de que el cliente pagará cualquier tipo de gasto económico que se haya realizado para cumplir con esta cotización los cuales deberán de ser debidamente comprobados al cliente. Todo servicio o equipo adicional al evento se documentará en hojas de cargo o misceláneo que formará parte de este instrumento. El cliente será responsable del equipo cuando lo reciba y cuidará de su total integridad y seguridad. En caso de no reintegrarse después de terminado el servicio cotizado, genera un cobro proporcional por dia de retrazo. Se puede confirmar esta cotizacion via mail , pero siempre en los términos de estas condiciones\nSi la cancelación es recibida con menos de 48 horas antes del evento se cargará 100% del total", "size": 8.5, "bold": false, "align": "justify", "colorToken": "ink", "wrap": true}]}'::jsonb, NULL, now(), NULL)
